style.css:
@-moz-document domain("roblox.com/home") {
/* === BASE === */
  html, body {
    background: #121212 !important;
    color: #e0e0e0 !important;
    font-family: "Segoe UI", Roboto, sans-serif !important;
  }

  /* === HEADERS === */
  h1, h2, h3, h4, h5, h6 {
    color: #ffffff !important;
  }

  /* === LINKS === */
  a {
    color: #66ccff !important;
  }

  a:hover {
    color: #00bfff !important;
    text-decoration: underline !important;
  }

  /* === NAVBAR === */
  header, .navbar, .nav-container, #navigation, #header {
    background: #1e1e1e !important;
    color: #ffffff !important;
  }

  /* === BUTTONS === */
  button, .btn-primary, .btn-secondary, .btn-control {
    background: #333 !important;
    color: #f1f1f1 !important;
    border: 1px solid #555 !important;
  }

  button:hover, .btn-primary:hover, .btn-secondary:hover, .btn-control:hover {
    background: #444 !important;
  }

  /* === SIDEBAR & PANELS === */
  .sidebar, .container-left, .container-right, .panel, .content {
    background: #1a1a1a !important;
    border-radius: 6px !important;
    padding: 1rem !important;
  }

  /* === FOOTER === */
  footer, #footer-container {
    background: #1e1e1e !important;
    color: #ccc !important;
  }

  /* === FORMS === */
  input, textarea, select {
    background: #1a1a1a !important;
    color: #f1f1f1 !important;
    border: 1px solid #444 !important;
  }

  input:focus, textarea:focus, select:focus {
    border-color: #66ccff !important;
  }

  /* === POPUPS, MODALS === */
  .modal-content, .modal-dialog, .chat-container {
    background: #1a1a1a !important;
    color: #f1f1f1 !important;
  }
}
